import random
from itertools import combinations

def has_short_cycle(adj, u, v, max_len=5):
    # BFS from u to v avoiding direct edge, find shortest path
    # If shortest path length <= max_len-1 before adding edge, then cycle length <= max_len
    # We want girth >= 6, so no cycles of length <= 5
    # After adding edge (u,v), shortest cycle through it = 1 + dist(u,v) in graph without edge
    # Need dist(u,v) >= 5 in current graph (without the edge)
    from collections import deque
    dist = {u: 0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_len:
            continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x] + 1
                if y == v:
                    return dist[y]  # length of path
                q.append(y)
    return dist.get(v, float('inf'))

def try_build(n=25, seed=0, max_deg=4, min_deg=3):
    random.seed(seed)
    adj = {i: set() for i in range(n)}
    edges = []
    # Greedy: build edges respecting girth >= 6 and degree <= 4
    pairs = list(combinations(range(n), 2))
    random.shuffle(pairs)
    for u, v in pairs:
        if len(adj[u]) >= max_deg or len(adj[v]) >= max_deg:
            continue
        d = has_short_cycle(adj, u, v, max_len=5)
        if d <= 4:  # would create cycle of length <= 5
            continue
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u, v))
    # Check min degree
    degs = [len(adj[i]) for i in range(n)]
    return edges, degs, adj

