# Compute girth via BFS from each vertex
def girth(adj, n):
    from collections import deque
    g = float('inf')
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = deque([s])
        while q:
            x = q.popleft()
            for y in adj[x]:
                if y not in dist:
                    dist[y] = dist[x]+1
                    parent[y] = x
                    q.append(y)
                elif parent[x] != y:
                    c = dist[x]+dist[y]+1
                    if c < g:
                        g = c
    return g

